 extern "C" void scan_and_histogram(const int64_t* in, int64_t* out, size_t n, uint64_t* hist) {
-    for (int b = 0; b < 256; ++b) hist[b] = 0;
+    // 8 private sub-histograms break the store-to-load dependency chain
+    // on hot bins (especially bin 0, which receives ~50% of all elements).
+    uint32_t h0[256] = {0};
+    uint32_t h1[256] = {0};
+    uint32_t h2[256] = {0};
+    uint32_t h3[256] = {0};
+    uint32_t h4[256] = {0};
+    uint32_t h5[256] = {0};
+    uint32_t h6[256] = {0};
+    uint32_t h7[256] = {0};
+
     int64_t sum = 0;
-    for (size_t i = 0; i < n; ++i) {
-        sum += in[i];
-        out[i] = sum;
-        hist[in[i] & 255]++;
+    const int64_t* p = in;
+    int64_t* q = out;
+    size_t remaining = n;
+
+    // 8-way unrolled main loop: consecutive hot-bin increments go to
+    // different arrays, so the CPU can overlap their store-to-load
+    // forwarding instead of serialising on one counter.
+    while (remaining >= 8) {
+        int64_t v0 = p[0];
+        int64_t v1 = p[1];
+        int64_t v2 = p[2];
+        int64_t v3 = p[3];
+        int64_t v4 = p[4];
+        int64_t v5 = p[5];
+        int64_t v6 = p[6];
+        int64_t v7 = p[7];
+
+        sum += v0; q[0] = sum;
+        sum += v1; q[1] = sum;
+        sum += v2; q[2] = sum;
+        sum += v3; q[3] = sum;
+        sum += v4; q[4] = sum;
+        sum += v5; q[5] = sum;
+        sum += v6; q[6] = sum;
+        sum += v7; q[7] = sum;
+
+        h0[v0 & 255]++;
+        h1[v1 & 255]++;
+        h2[v2 & 255]++;
+        h3[v3 & 255]++;
+        h4[v4 & 255]++;
+        h5[v5 & 255]++;
+        h6[v6 & 255]++;
+        h7[v7 & 255]++;
+
+        p += 8;
+        q += 8;
+        remaining -= 8;
+    }
+
+    // Tail (≤7 elements) – all go to h0; too few to cause contention.
+    while (remaining--) {
+        int64_t v = *p++;
+        sum += v;
+        *q++ = sum;
+        h0[v & 255]++;
+    }
+
+    // Combine sub-histograms into the final 64-bit counts.
+    for (int b = 0; b < 256; ++b) {
+        hist[b] = (uint64_t)h0[b] + h1[b] + h2[b] + h3[b] +
+                h4[b] + h5[b] + h6[b] + h7[b];
     }
 }
